-- Discovery of daily coverage, including previews; current day partial.
SELECT toDate(toTimeZone(timestamp,'Europe/Paris')) AS day, countIf(event='$pageview') AS pageviews, countIf(event='$web_vitals') AS web_vitals, countIf(event='$web_vitals' AND properties.$web_vitals_LCP_value IS NOT NULL) AS lcp, countIf(event='$web_vitals' AND properties.$web_vitals_FCP_value IS NOT NULL) AS fcp FROM events WHERE timestamp >= toDateTime('2026-09-30 22:00:00') AND timestamp < toDateTime('2026-10-29 16:08:00') AND event IN ('$pageview','$web_vitals') AND properties.$host='app.okado.app' GROUP BY day ORDER BY day LIMIT 40;

-- Route coverage, including previews; current day partial.
SELECT toDate(toTimeZone(timestamp,'Europe/Paris')) AS day, count() AS app_pageviews, countIf(properties.page='/other') AS generic_pageviews, countIf(properties.page IS NULL) AS legacy_pageviews FROM events WHERE timestamp >= toDateTime('2026-10-14 22:00:00') AND timestamp < toDateTime('2026-10-29 16:12:00') AND event='$pageview' AND properties.$host='app.okado.app' GROUP BY day ORDER BY day LIMIT 20;

-- Check each historical metric has no repeated pageview ID; IDs are not exported.
SELECT countIf(properties.$web_vitals_LCP_value IS NOT NULL) AS lcp_events, uniqIf(properties.$pageview_id,properties.$web_vitals_LCP_value IS NOT NULL) AS lcp_pageviews, countIf(properties.$web_vitals_FCP_value IS NOT NULL) AS fcp_events, uniqIf(properties.$pageview_id,properties.$web_vitals_FCP_value IS NOT NULL) AS fcp_pageviews FROM events WHERE event='$web_vitals' AND timestamp >= toDateTime('2026-09-30 22:00:00') AND timestamp < toDateTime('2026-10-28 23:00:00') AND properties.$host='app.okado.app';
